def fruit_distribution(s, n):
    counts = [int(x) for x in s.split() if x.isdigit()]
    if len(counts) != 2:
        return "Invalid input string"

    total_fruits = sum(counts)

    mangoes = n - total_fruits

    if mangoes < 0:
        return 0
    return mangoes

